   337		\begin{equation}
   338			\label{eq:gamma-value}
   339			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
   340		\end{equation}
